refentry.refsect1:
&reftitle.description;

 publicYaf_Controller_AbstractnullYaf_Action_Abstract::getController



 Récupère le contrôleur auquel appartient cette action.

&reftitle.returnvalues;

 Une instance de Yaf_Controller_Abstract, ou &null;
 si aucun contrôleur n'est disponible.

  &reftitle.examples;

   Exemple avec Yaf_Action_Abstract::getController


<?php
class ListAction extends Yaf_Action_Abstract
{
    public function execute() {
        // le contrôleur auquel appartient cette action
        $controller = $this->getController();
        var_dump($controller instanceof Yaf_Controller_Abstract);

        // par exemple, pour accéder à son moteur de vue
        $controller->getView()->assign("products", array("yaf", "php"));
    }
}
?>


   &example.outputs.similar;


bool(true)
